insert into public.questions (id, topic_id, level, type, prompt, code, correct, wrong, explanation, say_en, say_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('dev-git-M1', 'dev-git', 'Mid', 'mc', 'Un commit ya subido a main rompe producción. ¿Qué haces?', null, '`git revert <hash>`: crea un commit nuevo que deshace ese cambio sin reescribir el historial', array['`git reset --hard` y `push --force`', 'Borrar la rama main', 'Editar el commit antiguo']::text[], 'Revert es seguro en ramas compartidas porque no reescribe nada.', null, null, 'pending', true, null, null, null, null) on conflict (id) do update set topic_id = excluded.topic_id, level = excluded.level, type = excluded.type, prompt = excluded.prompt, code = excluded.code, correct = excluded.correct, wrong = excluded.wrong, explanation = excluded.explanation, say_en = excluded.say_en, say_es = excluded.say_es, status = excluded.status, active = excluded.active, es_prompt = excluded.es_prompt, es_correct = excluded.es_correct, es_wrong = excluded.es_wrong, es_explanation = excluded.es_explanation;
