insert into public.questions (id, topic_id, level, type, prompt, code, correct, wrong, explanation, say_en, say_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('dev-git-M3', 'dev-git', 'Mid', 'mc', '¿Diferencia entre merge y rebase?', null, 'merge une las ramas con un commit de merge conservando el historial; rebase reaplica tus commits encima de la otra rama y deja un historial lineal', array['Son iguales', 'rebase borra la otra rama', 'merge solo funciona en remoto']::text[], 'Rebase da un historial más limpio, pero reescribe tus commits.', null, null, 'pending', true, null, null, null, null) on conflict (id) do update set topic_id = excluded.topic_id, level = excluded.level, type = excluded.type, prompt = excluded.prompt, code = excluded.code, correct = excluded.correct, wrong = excluded.wrong, explanation = excluded.explanation, say_en = excluded.say_en, say_es = excluded.say_es, status = excluded.status, active = excluded.active, es_prompt = excluded.es_prompt, es_correct = excluded.es_correct, es_wrong = excluded.es_wrong, es_explanation = excluded.es_explanation;
