insert into public.questions (id, topic_id, level, type, prompt, code, correct, wrong, explanation, say_en, say_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('dev-git-S1', 'dev-git', 'Senior', 'mc', '¿Por qué no hacer rebase de una rama ya compartida?', null, 'Reescribe commits que otros ya tienen; obliga a forzar el push y puede hacer perder trabajo ajeno', array['Porque es más lento', 'Porque borra el historial de main', 'No hay ningún problema']::text[], 'Regla práctica: rebase en tus ramas locales, merge en las compartidas.', null, null, 'pending', true, null, null, null, null) on conflict (id) do update set topic_id = excluded.topic_id, level = excluded.level, type = excluded.type, prompt = excluded.prompt, code = excluded.code, correct = excluded.correct, wrong = excluded.wrong, explanation = excluded.explanation, say_en = excluded.say_en, say_es = excluded.say_es, status = excluded.status, active = excluded.active, es_prompt = excluded.es_prompt, es_correct = excluded.es_correct, es_wrong = excluded.es_wrong, es_explanation = excluded.es_explanation;
